import { createOptionalContext } from "../../utils/optional-context.js";
const [getOptionalReorderContext, setReorderContext] = createOptionalContext();
export { setReorderContext };
/** The closest Reorder.Group's context. */
export function getReorderContext() {
    const context = getOptionalReorderContext();
    if (!context)
        throw new Error("Reorder.Item must be a child of Reorder.Group");
    return context;
}
